files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #2b2b3a;
  background-image:
    linear-gradient(#444 1px, transparent 1px),
    linear-gradient(90deg, #444 1px, transparent 1px);
  background-size: 20px 20px;
  font-family: "Courier New", monospace;
  image-rendering: pixelated;
}

.quiz {
  background: #f5e9d0;
  border: 4px solid #111;
  box-shadow: 8px 8px 0 #111;
  padding: 24px;
  width: min(90vw, 420px);
  text-align: center;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.question-box {
  background: #fff;
  border: 3px solid #111;
  padding: 16px;
  font-size: 1.8rem;
  font-weight: bold;
  margin-bottom: 20px;
}

.answers {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 20px;
}

.pixel-btn {
  background: #f7d44a;
  border: 3px solid #111;
  box-shadow: 4px 4px 0 #111;
  padding: 12px 20px;
  font: inherit;
  font-size: 1.4rem;
  font-weight: bold;
  cursor: pointer;
  text-transform: uppercase;
}

.pixel-btn:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #111;
}

.pixel-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
  box-shadow: 4px 4px 0 #111;
}

.score-row {
  font-size: 1.2rem;
  margin-bottom: 20px;
}

.score-row output {
  font-weight: bold;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

const qEl = document.getElementById('question');
const aBtn = document.getElementById('answer-a');
const bBtn = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const questions = [
  { text: '2 + 2 = ?', answers: ['4', '5'], correct: 0 },
  { text: '3 + 3 = ?', answers: ['5', '6'], correct: 1 }
];

let current = 0;
let score = 0;
let answered = false;

function updateQuestion() {
  if (current < questions.length) {
    const q = questions[current];
    qEl.textContent = q.text;
    aBtn.textContent = q.answers[0];
    bBtn.textContent = q.answers[1];
    aBtn.disabled = false;
    bBtn.disabled = false;
    nextBtn.disabled = !answered;
  } else {
    qEl.textContent = 'Finished';
    aBtn.disabled = true;
    bBtn.disabled = true;
    nextBtn.disabled = true;
  }
}

function handleAnswer(index) {
  if (answered || current >= questions.length) return;
  answered = true;
  aBtn.disabled = true;
  bBtn.disabled = true;
  if (questions[current].correct === index) {
    score += 1;
    scoreEl.textContent = score;
  }
  nextBtn.disabled = false;
}

aBtn.addEventListener('click', () => handleAnswer(0));
bBtn.addEventListener('click', () => handleAnswer(1));

nextBtn.addEventListener('click', () => {
  if (!answered || current >= questions.length) return;
  current += 1;
  answered = false;
  if (current < questions.length) {
    nextBtn.disabled = true;
  }
  updateQuestion();
});

restartBtn.addEventListener('click', () => {
  current = 0;
  score = 0;
  answered = false;
  scoreEl.textContent = score;
  updateQuestion();
});

updateQuestion();
